// The slot this app's seeded roster belongs to. A manager who signs up claims a
// different slot, and the signed-in slot below takes precedence over this.
export const SEEDED_TEAM = "HELX";
export const MY_TEAM = SEEDED_TEAM;

// Whoever signed up on the sign-up page. Every screen reads the manager through
// these three, so a claimed slot and a custom franchise name actually take
// effect rather than sitting unused in storage.
export function manager() {
  try { return JSON.parse(localStorage.getItem("gl.manager")) || null; } catch (e) { return null; }
}
export function myTeam() {
  const m = manager();
  return (m && m.slot) || SEEDED_TEAM;
}
export function teamName(abbr) {
  const m = manager();
  if (m && m.slot === abbr && m.franchise) return m.franchise;
  return TEAM_NAMES[abbr] || abbr;
}
export function managerName(abbr) {
  const m = manager();
  if (m && m.slot === abbr && m.name) return m.name;
  return null;
}

import LOGO_INDEX from "./logos.index.json" with { type: "json" };
import HEADSHOTS from "./headshots.state.json" with { type: "json" };

export { LOGO_INDEX as LOGOS, HEADSHOTS };

// A player's team mark, served from public/assets/logos. The CDN is the
// fallback for any abbreviation the vendored set does not cover.
export function logo(team) {
  if (!team) return "";
  // "FA" is not a franchise, so there is no mark to request — asking the CDN for
  // one 404s on every surface that shows a free agent.
  if (String(team).toUpperCase() === "FA") return "";
  const k = String(team).toLowerCase() === "was" ? "wsh" : String(team).toLowerCase();
  const file = LOGO_INDEX[k];
  return file ? "/assets/logos/" + file : "https://a.espncdn.com/i/teamlogos/nfl/500-dark/" + k + ".png";
}

export function headshot(name) { return HEADSHOTS[name] || ""; }

// 2025 season line for a player, in the vocabulary of his own position.
export function statLine(p) {
  const de = p.p === "D/ST" ? DEFENSE[p.t] : null;
  if (de) return de.sack + " sacks · " + de.int + " INT · " + de.fr + " FR · " + (de.dtd + de.sptd) + " ret TD · " + de.fpts + " FPTS";
  const ki = KICK[p.n];
  if (ki) return ki.fg + "/" + ki.fga + " FG (" + ki.pct + "%) · " + ki.f50 + " from 50+ · LG " + ki.lg;
  const pa = PASS[p.n], ru = RUSH[p.n], re = RECV[p.n];
  const passing = pa ? pa.yds.toLocaleString() + " pass yds · " + pa.td + " TD · " + pa.int + " INT" : null;
  const rushing = (ru && ru.yds) ? ru.att + " att · " + ru.yds.toLocaleString() + " rush · " + ru.td + " TD" : null;
  const receiving = (re && re.rec) ? re.rec + " rec · " + re.yds.toLocaleString() + " yds · " + re.td + " TD" : null;
  // A player's own game leads: receivers and tight ends on receiving, backs on
  // rushing, quarterbacks on passing. The secondary line follows it.
  const order = p.p === "WR" || p.p === "TE"
    ? [receiving, rushing, passing]
    : p.p === "RB"
      ? [rushing, receiving, passing]
      : [passing, rushing, receiving];
  const bits = order.filter(Boolean);
  return bits.length ? bits.join(" · ") : "No 2025 production on file";
}

// The depth-chart label, falling back to a position rank where one exists.
export function roleOf(p) {
  if (ROLES[p.n]) return ROLES[p.n].role;
  if (KICK[p.n]) return "K" + KICK[p.n].rank;
  if (p.p === "D/ST" && DEFENSE[p.t]) return "DST" + DEFENSE[p.t].rank;
  return p.p;
}

export function ageOf(p) {
  return AGES[p.n] ? AGES[p.n].age : (DETAIL[p.n] ? DETAIL[p.n].age : null);
}
export function expOf(p) { return AGES[p.n] ? AGES[p.n].exp : null; }
export function byeOf(p) { return p.bye ?? (DETAIL[p.n] ? DETAIL[p.n].bye : null); }

export function find(name) { return POOL.find(p => p.n === name) || null; }
